Item.method_code:
const { excelConverterApi } = window;
const { item: itemJson } = options.getState();
const { contextItem: changes } = options.getProps()
const item = changes ? { ...itemJson, ...changes } : itemJson;
const worksheets = [];
const itemViewWorksheet = await excelConverterApi.convertItemView(item, options.itemType);
worksheets.push({
	...itemViewWorksheet,
	title: options.itemTypeName
});

const relationshipsContentWindow = window.findCurrentRelationshipsTab();
if (relationshipsContentWindow && relationshipsContentWindow.grid) {
	const grid = relationshipsContentWindow.grid._grid;
	const gridWorksheet = excelConverterApi.convertGrid(grid);
	worksheets.push({
		...gridWorksheet,
		title: relationshipsContentWindow.relationshipTypeName
	});
}

const fileName = aras.getResource('', 'aras_object.export2excel_file_prefix');
const fileBlob = await excelConverterApi.convertJsonToExcel(worksheets);
ArasModules.vault.saveBlob(fileBlob, `${fileName}.xlsx`);
